CSS = '''
:root{color-scheme:light;--ink:#1b2b44;--muted:#52647b;--line:#d9e2ec;--blue:#2162d3;--navy:#101633}*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:var(--ink);font:15px/1.65 system-ui,-apple-system,"PingFang SC",sans-serif}button,a{touch-action:manipulation}button{cursor:pointer;font:inherit;border-radius:9px;border:1px solid var(--line);background:white;color:var(--ink);padding:9px 12px;min-height:44px}button:hover{border-color:var(--blue);background:#edf4ff}button:focus-visible,a:focus-visible{outline:3px solid #d68a00;outline-offset:3px}.top{background:var(--navy);color:white;padding:25px max(24px,calc((100vw - 1300px)/2))}.eyebrow{font-size:12px;letter-spacing:.13em;color:#c9d9f3}h1{font-size:27px;margin:6px 0}h2{font-size:18px;margin:0 0 10px}p{margin:6px 0 14px}.top p{max-width:900px;color:#e1e7f2}.layout{max-width:1340px;display:grid;grid-template-columns:240px minmax(300px,440px) 1fr;gap:30px;margin:auto;padding:30px 24px}.nav{display:grid;gap:7px;align-content:start}.nav button{text-align:left;font-size:13px}.nav button[aria-current=page]{background:#e0ebfd;border-color:var(--blue);color:#144ca4}.phone{background:#eee;border:1px solid #cbd5df;border-radius:20px;overflow:hidden;box-shadow:0 9px 28px #19304f12;align-self:start}.phoneheader{background:#fff;padding:18px;border-bottom:1px solid var(--line);font-weight:650}.demo{font-size:11px;color:#6f4a00;background:#fff4d2;padding:6px 15px}.messages{padding:20px 15px;min-height:350px}.stamp{text-align:center;color:#627184;font-size:11px;margin-bottom:20px}.bubble{background:white;border-radius:10px;padding:13px 15px;margin:8px 0 17px;max-width:96%;overflow-wrap:anywhere;white-space:pre-line}.fromuser{background:#d7f1bd;margin-left:40px}.quote{border-left:3px solid #88a2c4;background:#e7edf4;color:#52647b;font-size:12px;padding:8px 11px;margin-bottom:10px}.taskcard{background:white;border:1px solid #d4dfec;border-top:3px solid var(--blue);border-radius:9px;padding:15px;white-space:pre-line;font-size:13px;overflow-wrap:anywhere}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:15px}.actions button{font-size:13px;color:#1858b4}.composer{display:flex;gap:7px;background:#f8fafc;padding:12px;border-top:1px solid var(--line)}.composer span{background:white;flex:1;border:1px solid #d7dfe8;border-radius:7px;padding:9px 10px;color:#69798c;font-size:12px}.inspector{align-self:start;background:white;border:1px solid var(--line);border-radius:13px;padding:24px}.pill{display:inline-block;background:#e7effc;color:#1d56a3;font-size:12px;padding:4px 9px;border-radius:20px;margin-bottom:16px}.note{padding:14px;background:#f4f7fc;border-radius:8px;margin:20px 0;font-size:13px}.links a{display:block;color:#1a56ad;margin:12px 0}footer{max-width:1280px;margin:0 auto;padding:10px 24px 35px;color:var(--muted);font-size:13px}.arrows{display:flex;gap:9px;margin-top:20px}.arrows button{flex:1}.print-only{display:none}@media(max-width:1050px){.layout{grid-template-columns:210px minmax(0,1fr);gap:20px}.inspector{grid-column:2}.phone{max-width:470px}}@media(max-width:650px){h1{font-size:23px}.top{padding:23px 16px}.layout{display:flex;flex-direction:column;padding:18px 12px}.nav{display:flex;max-width:100%;overflow-x:auto;padding-bottom:8px}.nav button{flex:0 0 170px}.phone,.inspector{width:100%;max-width:470px;align-self:center}.inspector{padding:20px}.messages{padding:16px 12px}.arrows button{min-width:0}.phoneheader{padding:15px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}@media print{.top,.layout,footer{display:none}.print-only{display:block}.sheet{page-break-after:always;padding:25px;font-size:13px}.sheet:last-child{page-break-after:auto}.sheet h1{font-size:21px}.sheet .phone{width:380px;margin:15px auto;box-shadow:none}.sheet .messages{min-height:0}.sheet .actions{display:grid}.sheet .composer{display:none}.sheet p{margin:10px 0}.sheet .demo{font-size:10px}@page{size:A4;margin:12mm}}
'''
JS = '''
let current = location.hash.slice(1) || 'digest';
let reviewVersion = 4;
const escapeHTML = s => s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function phone(s){
 if (["preview","approval-confirm","sent"].includes(s.id)) {
   s={...s,quote:s.quote.replaceAll("v4","v"+reviewVersion),bot:s.bot.replaceAll("v4","v"+reviewVersion),card:s.card.replaceAll("v4","v"+reviewVersion),actions:s.actions.map(([label,id])=>[label.replaceAll("v4","v"+reviewVersion),id])};
 }
 return `<div class="phone"><div class="phoneheader">${escapeHTML(s.channel)}</div><div class="demo">设计原型 · 示例客户 · 不连接真实任务或邮件</div><div class="messages"><div class="stamp">今日 · 09:42 · ${escapeHTML(s.state)}</div>${s.quote?`<div class="quote">引用：${escapeHTML(s.quote)}</div>`:''}${s.user?`<div class="bubble fromuser">${escapeHTML(s.user)}</div>`:''}<div class="bubble">${escapeHTML(s.bot)}</div><div class="taskcard">${escapeHTML(s.card)}<div class="actions">${s.actions.map(([label,id])=>`<button type="button" data-screen="${id}">${escapeHTML(label)}</button>`).join('')}</div></div></div><div class="composer"><span>请引用任务后说出操作或修改意见</span></div></div>`}
function render(id){const s=SCREENS.find(s=>s.id===id)||SCREENS[0];if(s.id==='ready')reviewVersion=3;if(s.id==='revised')reviewVersion=4;current=s.id;document.getElementById('stage').innerHTML=phone(s);document.getElementById('detail').innerHTML=`<div class="pill">${escapeHTML(s.state)}</div><h2>${escapeHTML(s.title)}</h2><p>${escapeHTML(s.explanation)}</p><div class="note">${escapeHTML(s.outcome)}</div><p>所有状态均为本轮建议。企微卡片、精确任务控制、私聊上下文及免重复登录尚未接到线上。</p><div class="links"><a href="assistant-ui.html">查看官网客服屏幕设计</a><a href="task-control-flow.html">查看任务控制时序图</a></div>`;document.querySelectorAll('.nav button').forEach(b=>b.setAttribute('aria-current',b.dataset.screen===s.id?'page':'false'));history.replaceState(null,'','#'+s.id);document.getElementById('status').textContent=s.title;}
document.getElementById('nav').innerHTML=SCREENS.map(s=>`<button type="button" data-screen="${s.id}">${escapeHTML(s.title)}</button>`).join('');
document.addEventListener('click',e=>{const b=e.target.closest('[data-screen]');if(b)render(b.dataset.screen)});
document.getElementById('previous').onclick=()=>render(SCREENS[(SCREENS.findIndex(s=>s.id===current)+SCREENS.length-1)%SCREENS.length].id);
document.getElementById('next').onclick=()=>render(SCREENS[(SCREENS.findIndex(s=>s.id===current)+1)%SCREENS.length].id);
document.getElementById('print').innerHTML=SCREENS.map(s=>`<section class="sheet"><h1>${escapeHTML(s.title)}</h1><p>企微交互设计 · 所有内容为样例，尚未实施</p>${phone(s)}<p>${escapeHTML(s.explanation)}</p><p>${escapeHTML(s.outcome)}</p></section>`).join('');render(current);
'''
